{
  "title": "Tính thể tích khối chóp S.MNPQR với đáy ngũ giác lõm",
  "description": "Chương trình này dựng hình khối chóp S.MNPQR với đáy là ngũ giác lõm MNPQR và tính thể tích của nó.",
  "memory_declarations": [
    {
      "name": "M",
      "type": "point3",
      "initial_value": [0, 0, 0],
      "source_fact_id": "m_coords"
    },
    {
      "name": "N",
      "type": "point3",
      "initial_value": [8, 0, 0],
      "source_fact_id": "n_coords"
    },
    {
      "name": "P",
      "type": "point3",
      "initial_value": [8, 6, 0],
      "source_fact_id": "p_coords"
    },
    {
      "name": "Q",
      "type": "point3",
      "initial_value": [4, 2, 0],
      "source_fact_id": "q_coords"
    },
    {
      "name": "R",
      "type": "point3",
      "initial_value": [0, 6, 0],
      "source_fact_id": "r_coords"
    },
    {
      "name": "S",
      "type": "point3",
      "initial_value": [3, 3, 9],
      "source_fact_id": "s_coords"
    },
    {
      "name": "base_mnpqr",
      "type": "polygon3",
      "model_assumption": "mnpqr_is_concave_pentagon"
    },
    {
      "name": "pyramid_s_mnpqr",
      "type": "solid",
      "model_assumption": "s_mnpqr_is_pyramid"
    },
    {
      "name": "V_S_MNPQR",
      "type": "float"
    }
  ],
  "statements": [
    {
      "kind": "declare_point",
      "target_var": "M",
      "at": [0, 0, 0],
      "source_fact_id": "m_coords",
      "label": "Điểm M"
    },
    {
      "kind": "declare_point",
      "target_var": "N",
      "at": [8, 0, 0],
      "source_fact_id": "n_coords",
      "label": "Điểm N"
    },
    {
      "kind": "declare_point",
      "target_var": "P",
      "at": [8, 6, 0],
      "source_fact_id": "p_coords",
      "label": "Điểm P"
    },
    {
      "kind": "declare_point",
      "target_var": "Q",
      "at": [4, 2, 0],
      "source_fact_id": "q_coords",
      "label": "Điểm Q"
    },
    {
      "kind": "declare_point",
      "target_var": "R",
      "at": [0, 6, 0],
      "source_fact_id": "r_coords",
      "label": "Điểm R"
    },
    {
      "kind": "declare_point",
      "target_var": "S",
      "at": [3, 3, 9],
      "source_fact_id": "s_coords",
      "label": "Đỉnh S"
    },
    {
      "kind": "construct_polygon",
      "target_var": "base_mnpqr",
      "vertices": ["M", "N", "P", "Q", "R"],
      "label": "Đáy ngũ giác MNPQR"
    },
    {
      "kind": "construct_solid",
      "target_var": "pyramid_s_mnpqr",
      "vertices": ["S", "M", "N", "P", "Q", "R"],
      "faces": [
        ["M", "N", "P", "Q", "R"],
        ["S", "M", "N"],
        ["S", "N", "P"],
        ["S", "P", "Q"],
        ["S", "Q", "R"],
        ["S", "R", "M"]
      ],
      "label": "Khối chóp S.MNPQR"
    },
    {
      "kind": "assign",
      "target_var": "V_S_MNPQR",
      "expr": {
        "kind": "measure",
        "quantity": "volume",
        "of": "pyramid_s_mnpqr"
      }
    }
  ],
  "pedagogical_intent": "Bài toán này minh họa cách dựng và tính thể tích khối chóp có đáy là một đa giác lõm trong không gian Oxyz, sử dụng các tọa độ điểm cho trước."
}
